      .replace(/[^{}]*@font-face[^{}]*{([^{}]+)}/gi, "$1")
      .split(";")
      .forEach((rule) => {
        if (rule.split(":")[0].trim())
          fontRules[rule.split(":")[0].trim()] = rule.split(":")[1].trim();
      });
    java.log(JSON.stringify(fontRules));
    //TODO: 懒得写了，解析字体地址

    style
      .replace(/[^{}]*@font-face[^{}]*{([^{}]+)}/gi, "")
      .match(/[^{}]+{[^{}]+}/gi)
      .forEach((set) => {
        selector = set.replace(/([^{}]+){([^{}]+)}/gi, "$1").trim();
        rules = {};
        set
          .replace(/([^{}]+){([^{}]+)}/gi, "$2")
          .split(";")
          .forEach((rule) => {
            if (rule.split(":")[0].trim())
              rules[rule.split(":")[0].trim()] = rule.split(":")[1].trim();
          });
        if (rules["font-family"]) {
