ruleToc.nextTocUrl:
@js:var doc = org.jsoup.Jsoup.parse(result);
// 定位“下一页”按钮：匹配文本为“下一页”（Unicode编码&#19979;&#19968;&#39029;）的a标签，优先取PC端（hidden-xs）容器内的元素
var nextLinkElem = doc.select("ul.pagination.pagination-lg.hidden-xs a.page_link:contains(下一页)").first();

// 若PC端未找到，再尝试从移动端（visible-xs）容器内查找
if (!nextLinkElem) {
    nextLinkElem = doc.select("ul.pagination.pager.visible-xs a#ff-next:contains(下一页)").first();
}

if (!nextLinkElem) {
    // 没找到下一页按钮，返回空
    "";
} else {
    var nextUrl = nextLinkElem.attr("href");
    // 从链接提取页码（匹配“-数字.html”格式，如43-2.html里的2）
    var pageMatch = nextUrl.match(/-(\d+)\.html/);

    if (!pageMatch) {
        // 页码格式不对，返回空
        "";
    } else {
        var nextPage = parseInt(pageMatch[1], 10);
        // 下一页页码≤10则返回链接，否则停止
        nextPage <= 10 ? nextUrl : "";
    }
}

